#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <functional>
#include <iostream>
#include <numeric>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

// 独立实现：目标顺序为 (身高降序, 体重降序)；
// 给每个学生编号，按目标顺序稳定排序（同身高同体重按原编号升序），
// 得到每个原位置的秩，最少相邻交换次数 = 秩序列的逆序对数（归并计数）。
static long long expected(const string& in) {
    istringstream iss(in);
    int n;
    iss >> n;
    vector<int> h(n), w(n), idx(n);
    for (int i = 0; i < n; i++) { iss >> h[i] >> w[i]; idx[i] = i; }
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (h[a] != h[b]) return h[a] > h[b];
        if (w[a] != w[b]) return w[a] > w[b];
        return a < b;
    });
    vector<int> rankAt(n);
    for (int r = 0; r < n; r++) rankAt[order[r]] = r;
    // 归并计数逆序对
    vector<int> tmp(n);
    long long inv = 0;
    function<long long(int, int, vector<int>&)> mergeCount =
        [&](int l, int r, vector<int>& arr) -> long long {
        if (r - l <= 1) return 0;
        int mid = l + (r - l) / 2;
        long long c = mergeCount(l, mid, arr) + mergeCount(mid, r, arr);
        int i = l, j = mid, k = l;
        while (i < mid && j < r) {
            if (arr[i] <= arr[j]) tmp[k++] = arr[i++];
            else { tmp[k++] = arr[j++]; c += (mid - i); }
        }
        while (i < mid) tmp[k++] = arr[i++];
        while (j < r) tmp[k++] = arr[j++];
        for (int t = l; t < r; t++) arr[t] = tmp[t];
        return c;
    };
    inv = mergeCount(0, n, rankAt);
    return inv;
}
static bool check(const string& exe, const string& in, int id) {
    const string inF = "l4a06p2_in.txt", outF = "l4a06p2_out.txt";
    {
        ofstream o(inF);
        o << in;
    }
    int code = system((exe + " < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream fis(outF);
    string got((istreambuf_iterator<char>(fis)), istreambuf_iterator<char>());
    long long exp = expected(in);
    long long g = -1;
    bool have = false;
    istringstream gs(got);
    if (gs >> g) have = true;
    if (code != 0 || !have || g != exp) {
        cout << "[FAIL] case " << id << ": status=" << code
             << ", actual=" << got.substr(0, 120) << ", expected=" << exp << "\n";
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<string> fixedCases = {
        "5\n1 60\n3 70\n2 80\n4 55\n4 50",
        "5\n4 0\n4 0\n2 0\n3 0\n1 0",
        "1\n5 5",
        "2\n1 1\n1 1",
        "3\n3 5\n2 9\n1 3",
    };
    for (size_t i = 0; i < fixedCases.size(); i++) {
        ++total;
        if (check(exe, fixedCases[i], 1 + i)) ++passed;
    }
    srand(20250602);
    for (int t = 0; t < 6; t++) {
        int n = 1 + rand() % 60;
        string in = to_string(n) + "\n";
        for (int i = 0; i < n; i++) {
            int h = rand() % 10, w = rand() % 10;
            in += to_string(h) + " " + to_string(w) + "\n";
        }
        ++total;
        if (check(exe, in, 6 + t)) ++passed;
    }
    for (int t = 0; t < 3; t++) {
        int n = 500 + rand() % 2500;
        string in = to_string(n) + "\n";
        for (int i = 0; i < n; i++) {
            int h = rand() % 1000, w = rand() % 1000;
            in += to_string(h) + " " + to_string(w) + "\n";
        }
        ++total;
        if (check(exe, in, 12 + t)) ++passed;
    }
    {
        int n = 3000;
        string in = to_string(n) + "\n";
        for (int i = 0; i < n; i++) {
            int h = rand() % 1000000001, w = rand() % 1000000001;
            in += to_string(h) + " " + to_string(w) + "\n";
        }
        ++total;
        if (check(exe, in, 15)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << "\n";
    return passed == total ? 0 : 1;
}
